        // '|| true': the normal case is "branch already exists" (422) — the
        // executor throws on non-zero exit, which would abort the commit.
        'gh api -X POST repos/' + repo + '/git/refs -f ref=refs/heads/' + branch +
            ' -f sha="$(gh api repos/' + repo +
